import { readdir, readFile, stat } from 'node:fs/promises';
const response = await fetch('http://localhost:3000');
const html = await response.text();
console.log(JSON.stringify({ status: response.status, catalog: html.includes('Product catalog'), products: ['Laptop', 'Phone', 'Tablet', 'Headphones', 'Watch'].every(name => html.includes(name)), form: html.match(/<form[\\s\\S]*?<\\/form>/)?.[0] }));
for (const name of await readdir('.next/cache/fetch-cache')) {
  const path = "'`.next/cache/fetch-cache/${name}`;
  const info = await stat(path);
  if (info.isFile()) console.log(JSON.stringify({ path, mtime: info.mtimeMs, cache: JSON.parse(await readFile(path, '"'utf8')) }));
}
NODE"

